def checkout(item_names):
    """Given names of items, build products and compute a total bill."""
    inv = load_default_inventory()
    products = []
    for name in item_names:
        p = inv.get(name)
        if p is None:
            continue
        products.append(p)
    total = bulk_price(products)
    return format_money(total)

def bulk_price(items):
    """Compute total given a list of products, with volume discount."""
    total = 0.0
    for p in items:
        total += p.price
    if len(items) >= 5:
        total *= 0.9
    return total

def format_money(amount):
    """Return amount formatted as dollars."""
    return f"${amount:.2f}"

def price_item(name):
    inv = load_default_inventory()
    p = inv.get(name)
    if p is None:
        return "unknown"
    discounted = apply_discount(p, 10)
    return format_money(discounted.price)

def apply_discount(product, percent):
    """Return a discounted copy of the product."""
    disc = product.price * (1 - percent / 100.0)
    return Product(product.name, disc)

class Product:
    """A product in the catalog."""

    def __init__(self, name, price):
        self.name = name
        self.price = price

    def tax(self, rate=0.08):
        return self.price * rate

class Inventory:
    """In-memory product database."""

    def __init__(self):
        self._items = {}

    def add(self, product):
        self._items[product.name] = product

    def get(self, name):
        return self._items.get(name)

    def total_value(self):
        sum_ = 0.0
        for p in self._items.values():
            sum_ += p.price
        return sum_

def __init__(self, name, price):
        self.name = name
        self.price = price

class LineItem:
    """A single line in a shopping cart."""

    def __init__(self, product, qty=1):
        self.product = product
        self.qty = qty

    def subtotal(self):
        return self.product.price * self.qty

